const deliveryLabels={web:'浏览器运行',download:'下载完整版',desktop:'桌面 App 运行',external:'外部平台'};
function safeLink(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}}
function cityModel(tax){return {population:Math.round(128-(tax-12)*2.8),happiness:Math.max(15,Math.round(88-(tax-8)*3)),revenue:Math.round(tax*(128-(tax-12)*2.8)*.8)}}
const city={id:'city',cat:'Simulation',title:'微型都市：你会怎样管理一座城？',desc:'先用 20 秒调整税率，再在桌面上建造完整的城市。',author:'Little Worlds',time:'20 秒切片',likes:426,plays:'18.2k',bg:'#e0ebdb',delivery:{type:'download',size:'2.4 GB',systems:'Windows / macOS',notes:'下载对应系统的安装包，完成安装后启动游戏。完整游戏包含城市建设、交通与长期经营。',demo:true}};
works.unshift(city);works.find(w=>w.id==='orbit').delivery={type:'desktop',size:'860 MB',systems:'Windows / macOS',appId:'kepler-orbital-lab',notes:'在 Slice 桌面 App 登录同一账号，进入 Library，找到「引力实验室」，安装后运行。',demo:true};
const priorStage=stage;stage=function(w){if(w.id!=='city')return priorStage(w);const m=cityModel(12);return `<div class="slice city-slice"><div class="city-label">MICRO CITY / 政策实验</div><h3>一座城，三种平衡。</h3><div class="city-metrics"><div><span>人口 / 千人</span><strong data-city-pop>${m.population}</strong></div><div><span>满意度</span><strong data-city-happy>${m.happiness}%</strong></div><div><span>收入 / 万</span><strong data-city-money>${m.revenue}</strong></div></div><div class="city-bar"><i style="width:${m.happiness}%"></i></div><label>税率 <input type="range" aria-label="城市税率" min="5" max="25" value="12" data-city-tax><output>12%</output></label><small>拖动税率，观察变化 · 简化演示模型</small></div>`};
document.addEventListener('input',e=>{if(!e.target.matches('[data-city-tax]'))return;const el=e.target.closest('.city-slice'),tax=+e.target.value,m=cityModel(tax);el.querySelector('output').textContent=tax+'%';el.querySelector('[data-city-pop]').textContent=m.population;el.querySelector('[data-city-happy]').textContent=m.happiness+'%';el.querySelector('[data-city-money]').textContent=m.revenue;el.querySelector('.city-bar i').style.width=m.happiness+'%'});
const storedLibrary=readStored('slice-library-v1',[]);let libraryIds=new Set((Array.isArray(storedLibrary)?storedLibrary:[]).filter(id=>typeof id==='string'));let libraryFilter='all';
const libraryButton=document.createElement('button');libraryButton.id='library-entry';libraryButton.innerHTML='▱ Library <span>0</span>';document.querySelector('#publish-entry').before(libraryButton);
const libraryDialog=document.createElement('dialog');libraryDialog.id='library-dialog';libraryDialog.setAttribute('aria-labelledby','library-title');document.body.append(libraryDialog);
function updateLibraryCount(){libraryButton.querySelector('span').textContent=works.filter(w=>libraryIds.has(w.id)).length}
function toggleLibrary(id){const next=new Set(libraryIds);next.has(id)?next.delete(id):next.add(id);try{localStorage.setItem('slice-library-v1',JSON.stringify([...next]))}catch{toast('收藏未保存，请检查浏览器存储空间');return}libraryIds=next;render();if(dialog.open)decorateWork(works.find(w=>w.id===activeId));if(libraryDialog.open)renderLibrary();toast(libraryIds.has(id)?'已收藏到 Library · 可稍后在桌面继续':'已从 Library 移除')}
const priorRender=render;render=function(){priorRender();document.querySelectorAll('#feed .card').forEach(card=>{const w=works.find(w=>'card-'+w.id===card.id),d=w.delivery||{type:'web'};const badge=document.createElement('div');badge.className='delivery-badge';badge.textContent=(d.type==='web'?'◎ ':'↗ ')+(deliveryLabels[d.type]||deliveryLabels.web)+(d.demo?' · 概念示例':'');card.querySelector('.card-meta').before(badge);const save=document.createElement('button');save.className='save-work'+(libraryIds.has(w.id)?' saved':'');save.dataset.save=w.id;save.setAttribute('aria-pressed',String(libraryIds.has(w.id)));save.textContent=libraryIds.has(w.id)?'✓ 已收藏':'＋ Library';card.querySelector('.card-actions').insertBefore(save,card.querySelector('[data-open]'));if(d.type!=='web')card.querySelector('[data-open]').textContent='完整Slice ↗'});updateLibraryCount()};
const deliveryBanner=document.createElement('section');deliveryBanner.className='app-downloads';deliveryBanner.setAttribute('aria-label','下载 Slice App');deliveryBanner.innerHTML=`<article class="app-download-card"><div class="app-platform">SLICE FOR MOBILE <span>iOS / Android</span></div><h2>把好奇心，装进口袋。</h2><p>随时刷到新Slice，直接试玩互动切片。把想深入体验的内容收藏进 Library，留给桌面继续。</p><div class="app-download-bottom"><button class="dark" type="button" disabled>下载手机 App · 即将上线</button><span>发现 · 试玩 · 收藏</span></div></article><article class="app-download-card desktop-download"><div class="app-platform">SLICE FOR DESKTOP <span>Windows / macOS</span></div><h2>让大Slice，尽情运行。</h2><p>集中管理 Library，下载并运行大型游戏、模拟器和创意工具。接续手机收藏，在桌面深度体验。</p><div class="app-download-bottom"><button class="dark" type="button" disabled>下载桌面 App · 即将上线</button><span>下载 · 运行 · 管理</span></div></article><p class="app-download-note">客户端功能规划 · 安装包与跨设备同步尚未开放。</p>`;document.querySelector('main#discover').append(deliveryBanner);
function linkButton(url,text){const safe=safeLink(url);return safe?`<a class="runtime-link" href="${escapeHtml(safe)}" target="_blank" rel="noopener noreferrer">${text} ↗</a>`:''}
function decorateWork(w){document.querySelector('#full-work-panel')?.remove();if(!w)return;const d=w.delivery||{type:'web'};document.querySelector('#dialog-mode').textContent=d.type==='web'?'PLAYGROUND · 浏览器体验':'INTERACTIVE SLICE · 完整Slice在下方获取';const panel=document.createElement('section');panel.id='full-work-panel';let actions='';if(d.type==='download'){actions=linkButton(d.windows,'下载 Windows 版')+linkButton(d.mac,'下载 macOS 版');if(!actions)actions='<p class="runtime-empty">概念示例：安装包尚未提供，当前不会开始下载。</p>'}else if(d.type==='desktop'){actions='<button type="button" class="dark" data-instructions>查看桌面运行说明 →</button>'}else if(d.type==='external'){actions=linkButton(d.url,'前往外部平台')||'<p class="runtime-empty">Slicer尚未配置平台链接。</p>'}else if(d.url){actions=linkButton(d.url,'打开完整网页版')}else{actions='<p class="runtime-empty">可直接在上方继续体验，无需安装。</p>'}panel.innerHTML=`<div class="full-heading"><div><span class="eyebrow">THE FULL EXPERIENCE</span><h3>${deliveryLabels[d.type]||deliveryLabels.web}</h3></div><button data-save="${w.id}" aria-pressed="${libraryIds.has(w.id)}">${libraryIds.has(w.id)?'✓ 已收藏到 Library':'＋ 收藏到 Library'}</button></div><div class="runtime-meta"><span>${escapeHtml(d.systems||'手机 / 网页')}</span>${d.size?`<span>${escapeHtml(d.size)}</span>`:''}<span>${d.type==='web'?'无需安装':'已收藏 ≠ 已安装'}</span></div><p>${escapeHtml(d.notes||(d.type==='web'?'在网页中直接探索这个Slice。':'先收藏，在合适的设备上继续。'))}</p><div class="runtime-actions">${actions}</div><div class="desktop-instructions" hidden><h4>如何在桌面继续</h4><ol><li>打开 Slice 桌面 App，登录同一个账号。</li><li>进入 Library，找到已收藏的Slice。</li><li>查看系统要求，下载并安装，然后启动。</li></ol>${d.appId?`<p>Slice标识：${escapeHtml(d.appId)}</p>`:''}<p class="prototype-note">此处演示未来流程。桌面 App、账号同步与安装功能尚未接入；不会尝试唤起或安装程序。</p></div>`;document.querySelector('#dialog-stage').after(panel);panel.querySelector('[data-instructions]')?.addEventListener('click',()=>{const box=panel.querySelector('.desktop-instructions');box.hidden=!box.hidden;panel.querySelector('[data-instructions]').textContent=box.hidden?'查看桌面运行说明 →':'收起运行说明 ↑'})}
const priorOpenWork=openWork;openWork=function(id,remix=false){const w=works.find(w=>w.id===id);if(remix&&id==='city'){toast('城市切片为概念示例，可在发布入口选择模板创作');return}document.querySelector('#full-work-panel')?.remove();priorOpenWork(id,remix);if(w&&!remix)decorateWork(w)};
function renderLibrary(){const list=works.filter(w=>libraryIds.has(w.id));const shown=list.filter(w=>libraryFilter==='all'||(libraryFilter==='desktop'&&['desktop','download'].includes(w.delivery?.type))||(libraryFilter==='web'&&(!w.delivery||w.delivery.type==='web')));libraryDialog.innerHTML=`<div class="dialog-head"><span>YOUR INTERACTIVE LIBRARY</span><button data-close-library aria-label="关闭 Library">✕</button></div><h2 id="library-title">先收下，留给下一次好奇。</h2><p>在手机发现，在网页收藏，在桌面继续。</p><div class="library-summary"><strong>${list.length} 个收藏</strong><span>${list.filter(w=>['download','desktop'].includes(w.delivery?.type)).length} 个适合桌面体验</span><span>本机保存 · 跨设备同步待接入</span></div><div class="library-filters"><button data-lib-filter="all" aria-pressed="${libraryFilter==='all'}">全部</button><button data-lib-filter="desktop" aria-pressed="${libraryFilter==='desktop'}">留给桌面</button><button data-lib-filter="web" aria-pressed="${libraryFilter==='web'}">网页可玩</button></div><div class="library-list">${shown.map(w=>{const d=w.delivery||{type:'web'};return `<article class="library-item"><div class="library-mark">${d.type==='web'?'◎':'↗'}</div><div><span>${escapeHtml(deliveryLabels[d.type]||deliveryLabels.web)}${d.size?' · '+escapeHtml(d.size):''}</span><h3>${escapeHtml(w.title)}</h3><p>${escapeHtml(w.author)} · 已收藏${d.type!=='web'?' / 未安装':''}</p></div><div class="library-item-actions"><button class="dark" data-library-open="${w.id}">${d.type==='web'?'继续体验':'查看获取方式'} ↗</button><button data-save="${w.id}">移除收藏</button></div></article>`}).join('')||'<div class="library-empty"><span>▱</span><h3>给下一次探索，留个位置。</h3><p>在Slice卡片点击「＋ Library」，即可收藏到这里。</p><button data-close-library>去发现Slice →</button></div>'}</div><div class="library-foot"><strong>你的桌面Slice库，从这里开始。</strong><p>收藏只记录你想体验的Slice，不代表购买、下载或安装。未来登录同一账号后，可将这些收藏同步到桌面 App。</p></div>`}
libraryButton.onclick=()=>{renderLibrary();libraryDialog.showModal()};document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.save)toggleLibrary(b.dataset.save);if(b.hasAttribute('data-close-library'))libraryDialog.close();if(b.dataset.libFilter){libraryFilter=b.dataset.libFilter;renderLibrary()}if(b.dataset.libraryOpen){libraryDialog.close();openWork(b.dataset.libraryOpen)}});
const deliveryFields=document.createElement('fieldset');deliveryFields.className='delivery-fields';deliveryFields.innerHTML=`<legend>完整Slice在哪里运行？</legend><p>上方是 Feed 里的轻量切片，下方决定用户如何继续。</p><label>交付方式 <select name="deliveryType"><option value="web">浏览器运行</option><option value="download">下载完整版</option><option value="desktop">在桌面 App 运行</option><option value="external">外部平台</option></select></label><div data-delivery-fields="web external"><label>完整Slice链接 <input name="deliveryUrl" type="url" placeholder="https://…"></label><small>网页版可留空，直接使用上方Slice；外部平台需填写链接。</small></div><div data-delivery-fields="download"><label>Windows 下载链接 <input name="deliveryWindows" type="url" placeholder="https://…"></label><label>macOS 下载链接 <input name="deliveryMac" type="url" placeholder="https://…"></label><small>至少填写一个真实的 HTTPS 下载地址。</small></div><div data-delivery-fields="desktop"><label>桌面 App Slice标识 <input name="deliveryAppId" maxlength="80" placeholder="例如 my-interactive-world"></label><small>当前仅展示运行说明，桌面 App 尚未接入。</small></div><div data-delivery-fields="download desktop"><label>支持系统 <input name="deliverySystems" maxlength="80" placeholder="例如 Windows 11 / macOS 14+"></label><label>下载大小 <input name="deliverySize" maxlength="30" placeholder="例如 2.4 GB"></label><label>安装与运行说明 <textarea name="deliveryNotes" maxlength="600" rows="3" placeholder="告诉用户如何继续体验完整Slice"></textarea></label></div>`;document.querySelector('.publish-fields').append(deliveryFields);
function syncDeliveryFields(){const mode=publishForm.elements.deliveryType.value;deliveryFields.querySelectorAll('[data-delivery-fields]').forEach(el=>{el.hidden=!el.dataset.deliveryFields.split(' ').includes(mode);el.querySelectorAll('input,textarea').forEach(input=>input.disabled=el.hidden)})}
publishForm.elements.deliveryType.onchange=syncDeliveryFields;syncDeliveryFields();
const previousFormData=formData;formData=function(){const d=previousFormData(),f=publishForm.elements;return {...d,delivery:{type:f.deliveryType.value,url:f.deliveryUrl.value.trim(),windows:f.deliveryWindows.value.trim(),mac:f.deliveryMac.value.trim(),appId:f.deliveryAppId.value.trim(),systems:f.deliverySystems.value.trim(),size:f.deliverySize.value.trim(),notes:f.deliveryNotes.value.trim()}}};
const previousCreator=openCreator;openCreator=function(work){previousCreator(work);const d=(work||readStored(draftKey,null))?.delivery;if(d){const mapping={deliveryType:'type',deliveryUrl:'url',deliveryWindows:'windows',deliveryMac:'mac',deliveryAppId:'appId',deliverySystems:'systems',deliverySize:'size',deliveryNotes:'notes'};for(const [field,key] of Object.entries(mapping))publishForm.elements[field].value=d[key]||'';if(!deliveryLabels[publishForm.elements.deliveryType.value])publishForm.elements.deliveryType.value='web'}syncDeliveryFields()};
const previousPublish=publishForm.onsubmit;publishForm.onsubmit=e=>{const d=formData().delivery;let error='';if(d.type==='download'&&!d.windows&&!d.mac)error='请至少填写一个系统的下载链接。';if(d.type==='external'&&!d.url)error='请填写外部平台链接。';if(d.type==='desktop'&&!d.appId)error='请填写桌面 App Slice标识。';const urls=d.type==='download'?[d.windows,d.mac]:['web','external'].includes(d.type)?[d.url]:[];if(urls.some(u=>u&&!safeLink(u)))error='请使用有效的 HTTPS 链接，且不要包含账号或密码。';if(error){e.preventDefault();document.querySelector('#publish-error').textContent=error;return}previousPublish(e);syncDeliveryFields()};
render();if(location.hash==='#library'){renderLibrary();libraryDialog.showModal()}else if(location.hash.startsWith('#work=')){openWork(location.hash.slice(6))}
window.addEventListener('hashchange',()=>{if(location.hash==='#library'){renderLibrary();if(!libraryDialog.open)libraryDialog.showModal()}});
